    color: var(--primary-color);
}

.blog-post {
    border-left: 4px solid var(--accent-color);
    padding: 1.5rem;
    margin: 2rem 0;
    background-color: var(--light-bg);
    border-radius: 4px;
}

.blog-post h3 {
    margin-top: 0;
}

.blog-post h3 a {
    color: var(--primary-color);
    text-decoration: none;
}

.blog-post h3 a:hover {
    color: var(--accent-color);
}

.post-meta {
    color: #666;
    font-size: 0.9rem;
    margin-top: 0.5rem;
}

ul.principles {
    list-style: none;
    margin: 1rem 0;
}

ul.principles li {
    padding: 1rem;
    margin: 0.5rem 0;
    background-color: var(--light-bg);
    border-left: 4px solid var(--accent-color);
    border-radius: 4px;
}

ul {
    margin-left: 2rem;
    margin-bottom: 1rem;
}

li {
    margin: 0.5rem 0;
}

a {
    color: var(--accent-color);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

footer {
    background-color: var(--primary-color);
    color: white;
    text-align: center;
    padding: 2rem;
    margin-top: 4rem;
}

@media (max-width: 768px) {
    header {
        padding: 1rem;
    }

    header h1 {
        font-size: 1.5rem;
    }

    nav {
        flex-direction: column;
        gap: 0.5rem;
    }

    main {
        padding: 1rem;
    }

    .hero h2 {
        font-size: 1.5rem;
    }

    .focus-areas {
        grid-template-columns: 1fr;
    }
}

